import Cocoa
@main struct NativeSyncTests {
 static func main(){NSApplication.shared.setActivationPolicy(.prohibited);let node=SyncNode(directory:false,size:5,modified:100);let candidate=SyncCandidate(relative:"file.txt",local:node,remote:nil,upload:true,selected:true,typeConflict:false);let conflict=SyncCandidate(relative:"conflict.txt",local:node,remote:node,upload:nil,selected:false,typeConflict:false);let controller=SyncPreviewController(candidates:[candidate,conflict]);controller.window!.contentView!.layoutSubtreeIfNeeded();precondition(!controller.window!.isVisible && controller.table.enclosingScrollView!.frame.height>=240);controller.selectNone();precondition(controller.candidates.allSatisfy{!$0.selected});controller.selectExecutable();precondition(controller.candidates[0].selected && !controller.candidates[1].selected);controller.selectNone();controller.table.selectRowIndexes(IndexSet(integer:1),byExtendingSelection:false);controller.useRemote();precondition(controller.candidates[1].upload==false && controller.candidates[1].selected);var applied=[SyncCandidate]();controller.onApply={applied=$0};controller.apply();precondition(applied.count==1 && applied[0].relative=="conflict.txt");print("PASS: hidden native sync-preview layout, select-all excludes unresolved conflicts, explicit row resolution, apply only checked items")}
